/**
 * Music Session — the "say what you want to make" engine.
 *
 * Replaces the old static nine-row beginner checklist. The interaction is
 * modeled on how the owner actually works with ChatGPT and Claude: say the
 * goal, get ONE next move, copy it somewhere useful, do the work, paste back
 * what happened, keep going. No AI call happens here — every move is a
 * deterministic template built from the goal text, the chosen tool, and
 * whatever the creator pasted back last. Nothing here is generated by a
 * model, and nothing here claims to be.
 *
 * Pure functions only — persistence lives in music-session.store.ts, UI in
 * MusicSession.tsx.
 */

// ---------------------------------------------------------------------------
// Tools — kept lightweight on purpose. "Not sure yet" is a valid answer.
// ---------------------------------------------------------------------------

export type Tool =
  | "bandlab" | "garageband" | "ableton" | "fl-studio"
  | "logic" | "ardour" | "mpc" | "other" | "unsure";

export const TOOL_LABELS: Record<Tool, string> = {
  bandlab: "BandLab",
  garageband: "GarageBand",
  ableton: "Ableton",
  "fl-studio": "FL Studio",
  logic: "Logic",
  ardour: "Ardour",
  mpc: "MPC",
  other: "Other",
  unsure: "Not sure yet",
};

export const TOOLS = Object.keys(TOOL_LABELS) as Tool[];

// ---------------------------------------------------------------------------
// Stages — the subtle progress rail. Six stages, seven moves (Finish holds two).
// ---------------------------------------------------------------------------

export type MusicStage = "idea" | "groove" | "bass" | "music" | "arrange" | "finish";

export const STAGE_LABELS: Record<MusicStage, string> = {
  idea: "Idea",
  groove: "Groove",
  bass: "Bass",
  music: "Music",
  arrange: "Arrange",
  finish: "Finish",
};

export const STAGE_ORDER: MusicStage[] = ["idea", "groove", "bass", "music", "arrange", "finish"];

// ---------------------------------------------------------------------------
// Profile detection — a small number of sensible pathways, not a genre engine.
// ---------------------------------------------------------------------------

export type Profile = "reggae" | "hiphop" | "piano" | "ambient" | "existing-idea" | "generic";

export function detectProfile(goal: string): Profile {
  const g = goal.toLowerCase();
  if (/reggae|dub\b|one.?drop|\bska\b/.test(g)) return "reggae";
  if (/hip.?hop|\btrap\b|boom.?bap|\brap\b/.test(g)) return "hiphop";
  if (/\bpiano\b|solo keys|keys idea/.test(g)) return "piano";
  if (/\bgame\b|background music|\bambient\b|\bscore\b|underscore/.test(g)) return "ambient";
  if (/already (have|started|wrote|working)|half.?finished|existing (idea|song)|idea i (already )?have/.test(g)) return "existing-idea";
  return "generic";
}

// ---------------------------------------------------------------------------
// Moves — one deterministic next step at a time.
// ---------------------------------------------------------------------------

export interface Move {
  index: number;
  stage: MusicStage;
  title: string;
  detail: string;
  copyText: string;
}

export const TOTAL_MOVES = 7;

function toolPrefix(tool: Tool): string {
  return tool === "unsure" ? "In your music app, " : `In ${TOOL_LABELS[tool]}, `;
}

function toolFor(tool: Tool): string {
  return tool === "unsure" ? "in my music app (I haven't picked one yet)" : `in ${TOOL_LABELS[tool]}`;
}

function goalSentence(goal: string): string {
  return goal.trim() ? `I'm working on: "${goal.trim()}".` : "I'm making my first beat.";
}

function assistantPrompt(ctx: { goal: string; tool: Tool; lastNote?: string }, task: string): string {
  const note = ctx.lastNote?.trim();
  const notePart = note ? ` Last update: ${note}${/[.!?]$/.test(note) ? "" : "."}` : "";
  return `Help me ${task} ${toolFor(ctx.tool)}. ${goalSentence(ctx.goal)}${notePart} Give me only the next small step. Keep it beginner-friendly.`;
}

