export function buildMove(index: number, ctx: { goal: string; tool: Tool; profile: Profile; lastNote?: string }): Move {
  const content = PROFILE_CONTENT[ctx.profile];
  const isExisting = ctx.profile === "existing-idea";

  switch (index) {
    case 0:
      return isExisting
        ? {
            index, stage: "idea",
            title: "Open what you already have",
            detail: "Open the project, voice memo, or file where this idea already lives, and play it once, start to finish, so it's fresh.",
            copyText: assistantPrompt(ctx, "pick up a song idea I already started"),
          }
        : {
            index, stage: "idea",
            title: "Set up a simple project",
            detail: `${toolPrefix(ctx.tool)}create a new project and set the tempo to 90 BPM — a comfortable starting speed you can change any time.`,
            copyText: assistantPrompt(ctx, "start a new project and set a comfortable tempo"),
          };
    case 1:
      return { index, stage: "groove", title: content.groove.title, detail: `${toolPrefix(ctx.tool)}${content.groove.detail[0].toLowerCase()}${content.groove.detail.slice(1)}`, copyText: assistantPrompt(ctx, content.groove.task) };
    case 2:
      return { index, stage: "bass", title: content.bass.title, detail: content.bass.detail, copyText: assistantPrompt(ctx, content.bass.task) };
    case 3:
      return { index, stage: "music", title: content.music.title, detail: content.music.detail, copyText: assistantPrompt(ctx, content.music.task) };
    case 4:
      return {
        index, stage: "arrange",
        title: "Arrange a beginning, middle, and end",
        detail: "Intro: sparse, just one or two elements. Middle: everything together. End: strip parts back out. 30–60 seconds total is a real first track.",
        copyText: assistantPrompt(ctx, "arrange what I have into a beginning, middle, and end, 30 to 60 seconds"),
      };
    case 5:
      return {
        index, stage: "finish",
        title: "Listen back start to finish",
        detail: "Play it all the way through once. Notice what feels good and what feels empty — nothing to fix yet, just listen.",
        copyText: assistantPrompt(ctx, "tell me what to listen for on a first full playback"),
      };
    default:
      return {
        index, stage: "finish",
        title: "Export the audio",
        detail: `${toolPrefix(ctx.tool)}export or bounce the track as an MP3 or WAV, and save it where you can find it.`,
        copyText: assistantPrompt(ctx, "export or bounce this to a real MP3 or WAV file"),
      };
  }
}

// ---------------------------------------------------------------------------
// The session record — one active session at a time.
// ---------------------------------------------------------------------------

export interface LogEntry {
  stepIndex: number;
  note: string;
  at: string;
}

export const MUSIC_SESSION_VERSION = 1;

export interface MusicSessionV1 {
  version: 1;
  id: string;
  goal: string;
  tool: Tool;
  profile: Profile;
  stepIndex: number;
  log: LogEntry[];
  createdAt: string;
  updatedAt: string;
  finishedAt: string | null;
}

let counter = 0;
export function sessionUid(): string {
  counter += 1;
  return `${Date.now().toString(36)}-${counter.toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
}

export function startSession(goal: string, tool: Tool, now?: string): MusicSessionV1 {
  const at = now ?? new Date().toISOString();
  return {
    version: 1,
    id: sessionUid(),
    goal: goal.trim(),
    tool,
    profile: detectProfile(goal),
    stepIndex: 0,
    log: [],
    createdAt: at,
    updatedAt: at,
    finishedAt: null,
  };
}

export function currentMove(session: MusicSessionV1): Move {
  const lastNote = session.log[session.log.length - 1]?.note;
  return buildMove(session.stepIndex, { goal: session.goal, tool: session.tool, profile: session.profile, lastNote });
}

export function isFinished(session: MusicSessionV1): boolean {
  return session.finishedAt !== null || session.stepIndex >= TOTAL_MOVES;
}

/** Records what happened and moves to the next step. A blank note is valid — "done" needs no explanation. */
export function advance(session: MusicSessionV1, note: string, now?: string): MusicSessionV1 {
  if (isFinished(session)) return session;
  const at = now ?? new Date().toISOString();
  const nextIndex = session.stepIndex + 1;
  return {
    ...session,
    stepIndex: nextIndex,
    log: [...session.log, { stepIndex: session.stepIndex, note: note.trim(), at }],
    updatedAt: at,
    finishedAt: nextIndex >= TOTAL_MOVES ? at : null,
  };
}

export interface Progress {
  stage: MusicStage;
  stageIndex: number;
  stageCount: number;
  moveIndex: number;
  moveCount: number;
}

export function progress(session: MusicSessionV1): Progress {
  const idx = Math.min(session.stepIndex, TOTAL_MOVES - 1);
  const move = buildMove(idx, { goal: session.goal, tool: session.tool, profile: session.profile });
  return {
    stage: move.stage,
    stageIndex: STAGE_ORDER.indexOf(move.stage),
    stageCount: STAGE_ORDER.length,
    moveIndex: session.stepIndex,
    moveCount: TOTAL_MOVES,
  };
}

// ---------------------------------------------------------------------------
// Stuck help — deterministic, tool-aware, never a guess dressed as fact.
// ---------------------------------------------------------------------------

const STUCK_BY_TOOL: Record<Tool, string> = {
  bandlab: "Look for the \"+\" button to add a new track, then choose an instrument or the Beat Maker.",
  garageband: "Track menu → New Track, then choose Drummer or a Software Instrument.",
  ableton: "Use the browser panel on the left — drag an instrument or Drum Rack onto a new MIDI track.",
  "fl-studio": "Open the Channel Rack (F6) and add or browse instruments from there.",
  logic: "Track menu → New Track → Software Instrument, then pick a patch.",
  ardour: "Ardour is mainly a recording and mixing tool — it may need an instrument plugin added to a MIDI track first.",
  mpc: "Load a program onto a track, then tap pads or keys to trigger sounds.",
  other: "Look for \"Add Track\" or a \"+\" button, then choose an instrument.",
  unsure: "Look for \"Add Track\" or a \"+\" button in your app, then choose an instrument.",
};

export function stuckHelp(tool: Tool): string[] {
  return [
    STUCK_BY_TOOL[tool],
    "If sound isn't working: check the tab or app isn't muted, and click inside the project once — some tools block audio until you interact with the page.",
    "Paste what you're seeing below and keep going — the next move will adjust.",
  ];
}

// ---------------------------------------------------------------------------
// Safe parse — never destroy an existing session on a bad read.
// ---------------------------------------------------------------------------

function str(v: unknown, fallback = ""): string {
  return typeof v === "string" ? v : fallback;
}
function num(v: unknown, fallback = 0): number {
  return typeof v === "number" && Number.isFinite(v) ? v : fallback;
}
function oneOf<T extends string>(v: unknown, allowed: readonly T[], fallback: T): T {
  return typeof v === "string" && (allowed as readonly string[]).includes(v) ? (v as T) : fallback;
}

export function parseSession(v: unknown): MusicSessionV1 | null {
  if (!v || typeof v !== "object") return null;
  const o = v as Record<string, unknown>;
  if (typeof o.id !== "string" || !o.id) return null;

  const goal = str(o.goal);
  return {
    version: 1,
    id: o.id,
    goal,
    tool: oneOf(o.tool, TOOLS, "unsure"),
    profile: oneOf(o.profile, ["reggae", "hiphop", "piano", "ambient", "existing-idea", "generic"] as const, detectProfile(goal)),
    stepIndex: Math.max(0, Math.min(TOTAL_MOVES, num(o.stepIndex))),
    log: Array.isArray(o.log)
      ? o.log.flatMap((e): LogEntry[] => {
          if (!e || typeof e !== "object") return [];
          const x = e as Record<string, unknown>;
          return [{ stepIndex: num(x.stepIndex), note: str(x.note), at: str(x.at, new Date().toISOString()) }];
        })
      : [],
    createdAt: str(o.createdAt, new Date().toISOString()),
    updatedAt: str(o.updatedAt, new Date().toISOString()),
    finishedAt: typeof o.finishedAt === "string" ? o.finishedAt : null,
  };
}
